        "Cnaes.zip": {"CNAECSV.csv": '"0111301";"Cultivo de café"\n'},
        "Empresas0.zip": {"0.EMPRECSV.csv": '"00000001";"Café Brasil";"2062";"49";"1.234,56";"01";""\n'},
